-- APPLY-BY: ci
-- DB: qnfo-audit
-- BACKUP: bak_20261114_closing_probe_adopt
-- Rollback: UPDATE remediation_contracts SET status = (SELECT b.status FROM bak_20261114_closing_probe_adopt b WHERE b.class = remediation_contracts.class), last_verdict = (SELECT b.last_verdict FROM bak_20261114_closing_probe_adopt b WHERE b.class = remediation_contracts.class), verify_probe = (SELECT b.verify_probe FROM bak_20261114_closing_probe_adopt b WHERE b.class = remediation_contracts.class), next_due_at = (SELECT b.next_due_at FROM bak_20261114_closing_probe_adopt b WHERE b.class = remediation_contracts.class) WHERE class IN (SELECT class FROM bak_20261114_closing_probe_adopt) AND (last_verdict LIKE 'rearmed: CLOSING-PROBE-ADOPT-1%' OR verify_probe LIKE '%''dangling:r2:%'); UPDATE fleet_crons SET enabled = 0 WHERE name = 'closing-probe-adopt-hourly'; UPDATE fleet_tasks SET enabled = 0 WHERE id = 'closing-probe-adopt'
-- CAUSE-MAPPED: registers no metric; the detector is a failure-mode contract (fm-loop-owned-wait-hides-own-probe), not a metric_registry row.
-- CLOSING-PROBE-ADOPT-1 (2026-11-14, charter pillar: autonomy; owner 2026-11-14: "why are there open issues? I want all issues drained").
-- Measured 2026-11-14 ~14:30Z in qnfo-audit: 716 open agent_issues; 200 opened and 78 closed in 24 h (drain 0.39, target >= 1.5). 183 open issues sit behind
-- a contract that reads 'monitoring:loop-owned-48h': contract_probe_templates_loop_merged parks every issue a live worker files as monitoring with
-- next_due_at NULL (never probed) and waits for "the filing loop closes it". Many filing loops never close their own issues, so the issue waits out 48 h
-- and then goes stale, even when it carries its own machine-checkable `closing probe: SELECT ...` line that would pass now (53 of the 183).
-- First case: 38 CF-RESOURCE-UNUSED-1 issues filed at 2026-11-14T00:02Z by qnfo-cloud-ops when its worker-usage GraphQL read timed out (every worker read
-- 0 requests: qnfo-ai, qnfo-ops, qnfo-fleet-control ...). The registry reads them 'ok' again since 01:01Z (qnfo-ops 32,901 requests in 7 days), yet all 38
-- stayed open. The worker fix (CF-RESOURCE-USAGE-HONEST-1, qnfo-cloud-ops) stops the false filing; this file closes the loop for every filer.
-- WHAT THIS DOES: (1) keeps the before-state in bak_20261114_closing_probe_adopt; (2) for an open issue whose contract is loop-owned monitoring and whose
-- description carries a single-statement, read-only `closing probe: SELECT ... AS expected ... AS observed` line, the contract adopts that probe and is set
-- active and due now, so the remediation consumer probes it and remediation_verification_autoclose_ins closes the issue on a pass (REMEDIATION-REOPEN-2
-- reopens it on relapse); (3) repairs the 13 CF-RESOURCE-DANGLING-1 probes, which named 'r2:<name>' while the registry row is 'dangling:r2:<name>';
-- (4) the hourly workflow closing-probe-adopt (fleet_tasks + fleet_crons, :35) repeats (1) and (2) for issues filed later; (5) failure mode
-- loop-owned-wait-hides-own-probe with detector fm-loop-owned-wait-hides-own-probe. No trigger is added to agent_issues (AGENT-ISSUES-TRIGGER-DEPTH-1);
-- nothing is closed by this file: every close goes through a passing probe.
-- Prediction: within 3 h, >= 38 of the 53 adoptable issues close through auto:verified-remediation-trigger; issue_drain_ratio_24h rises.
-- Verify:
--   SELECT COUNT(*) FROM bak_20261114_closing_probe_adopt;                                                  -- >= 53
--   SELECT COUNT(*) FROM agent_issues WHERE status = 'open' AND title LIKE 'CF-RESOURCE-UNUSED-1:%';        -- 0 within 3 h
--   SELECT last_fired FROM fleet_crons WHERE name = 'closing-probe-adopt-hourly';                           -- within the hour

CREATE TABLE IF NOT EXISTS bak_20261114_closing_probe_adopt (class TEXT PRIMARY KEY, issue_id INTEGER, status TEXT, last_verdict TEXT, verify_probe TEXT, next_due_at TEXT, saved_at TEXT);

-- 1. before-state (also the first step of the hourly workflow)
INSERT INTO bak_20261114_closing_probe_adopt (class, issue_id, status, last_verdict, verify_probe, next_due_at, saved_at) SELECT c.class, c.issue_id, c.status, c.last_verdict, c.verify_probe, c.next_due_at, datetime('now') FROM remediation_contracts c WHERE c.class IN (SELECT class FROM (SELECT c.class, trim(CASE WHEN instr(a.p, char(10)) > 0 THEN substr(a.p, 1, instr(a.p, char(10)) - 1) ELSE a.p END) AS probe FROM remediation_contracts c JOIN (SELECT id, substr(description, instr(description, 'closing probe: ') + 15) AS p FROM agent_issues WHERE status = 'open' AND instr(description, 'closing probe: SELECT') > 0) a ON c.class = 'issue-' || a.id WHERE c.last_verdict LIKE 'monitoring:loop-owned%') WHERE instr(probe, char(59)) = 0 AND length(probe) BETWEEN 30 AND 2000 AND lower(probe) LIKE 'select %' AND lower(probe) LIKE '% as expected%' AND lower(probe) LIKE '% as observed%' AND lower(probe) NOT LIKE '%insert %' AND lower(probe) NOT LIKE '%update %' AND lower(probe) NOT LIKE '%delete %' AND lower(probe) NOT LIKE '%drop %' AND lower(probe) NOT LIKE '%alter %' AND lower(probe) NOT LIKE '%create %' AND lower(probe) NOT LIKE '%attach %' AND lower(probe) NOT LIKE '%pragma%' AND lower(probe) NOT LIKE '%replace into%') AND NOT EXISTS (SELECT 1 FROM bak_20261114_closing_probe_adopt b WHERE b.class = c.class);

-- 2. adopt the issue's own probe (also the second step of the hourly workflow)
WITH x AS (SELECT c.class, trim(CASE WHEN instr(a.p, char(10)) > 0 THEN substr(a.p, 1, instr(a.p, char(10)) - 1) ELSE a.p END) AS probe FROM remediation_contracts c JOIN (SELECT id, substr(description, instr(description, 'closing probe: ') + 15) AS p FROM agent_issues WHERE status = 'open' AND instr(description, 'closing probe: SELECT') > 0) a ON c.class = 'issue-' || a.id WHERE c.last_verdict LIKE 'monitoring:loop-owned%') UPDATE remediation_contracts SET verify_probe = (SELECT probe FROM x WHERE x.class = remediation_contracts.class), status = 'active', attempts = 0, next_due_at = datetime('now'), last_verdict = 'rearmed: CLOSING-PROBE-ADOPT-1 (the issue''s own closing probe replaces the loop-owned 48h wait)' WHERE class IN (SELECT class FROM x WHERE instr(probe, char(59)) = 0 AND length(probe) BETWEEN 30 AND 2000 AND lower(probe) LIKE 'select %' AND lower(probe) LIKE '% as expected%' AND lower(probe) LIKE '% as observed%' AND lower(probe) NOT LIKE '%insert %' AND lower(probe) NOT LIKE '%update %' AND lower(probe) NOT LIKE '%delete %' AND lower(probe) NOT LIKE '%drop %' AND lower(probe) NOT LIKE '%alter %' AND lower(probe) NOT LIKE '%create %' AND lower(probe) NOT LIKE '%attach %' AND lower(probe) NOT LIKE '%pragma%' AND lower(probe) NOT LIKE '%replace into%');

-- 3. one-time: the dangling probes name the registry row they mean (backup first)
INSERT OR IGNORE INTO bak_20261114_closing_probe_adopt (class, issue_id, status, last_verdict, verify_probe, next_due_at, saved_at) SELECT c.class, c.issue_id, c.status, c.last_verdict, c.verify_probe, c.next_due_at, datetime('now') FROM remediation_contracts c WHERE c.class IN (SELECT 'issue-' || id FROM agent_issues WHERE status = 'open' AND title LIKE 'CF-RESOURCE-DANGLING-1: % %') AND c.verify_probe LIKE '%FROM cf_resource_registry WHERE id = ''r2:%';
UPDATE remediation_contracts SET verify_probe = (SELECT 'SELECT ''ok'' AS expected, CASE WHEN verdict IN (''ok'', ''resolved'') THEN ''ok'' ELSE verdict END AS observed FROM cf_resource_registry WHERE id = ''dangling:' || replace(substr(a.title, 25), ' ', ':') || '''' FROM agent_issues a WHERE 'issue-' || a.id = remediation_contracts.class) WHERE class IN (SELECT 'issue-' || id FROM agent_issues WHERE status = 'open' AND title LIKE 'CF-RESOURCE-DANGLING-1: % %') AND verify_probe LIKE '%FROM cf_resource_registry WHERE id = ''r2:%';

-- 4. the hourly workflow
INSERT INTO fleet_tasks (id, name, type, definition, timeout_ms, retries, version, enabled, updated_at)
VALUES ('closing-probe-adopt', 'CLOSING-PROBE-ADOPT-1: a loop-filed issue that carries its own read-only closing probe is probed by it instead of waiting 48 h for the filing loop', 'workflow', '{"steps":[{"type":"sql","db":"AUDIT","sql":"INSERT INTO bak_20261114_closing_probe_adopt (class, issue_id, status, last_verdict, verify_probe, next_due_at, saved_at) SELECT c.class, c.issue_id, c.status, c.last_verdict, c.verify_probe, c.next_due_at, datetime(''now'') FROM remediation_contracts c WHERE c.class IN (SELECT class FROM (SELECT c.class, trim(CASE WHEN instr(a.p, char(10)) > 0 THEN substr(a.p, 1, instr(a.p, char(10)) - 1) ELSE a.p END) AS probe FROM remediation_contracts c JOIN (SELECT id, substr(description, instr(description, ''closing probe: '') + 15) AS p FROM agent_issues WHERE status = ''open'' AND instr(description, ''closing probe: SELECT'') > 0) a ON c.class = ''issue-'' || a.id WHERE c.last_verdict LIKE ''monitoring:loop-owned%'') WHERE instr(probe, char(59)) = 0 AND length(probe) BETWEEN 30 AND 2000 AND lower(probe) LIKE ''select %'' AND lower(probe) LIKE ''% as expected%'' AND lower(probe) LIKE ''% as observed%'' AND lower(probe) NOT LIKE ''%insert %'' AND lower(probe) NOT LIKE ''%update %'' AND lower(probe) NOT LIKE ''%delete %'' AND lower(probe) NOT LIKE ''%drop %'' AND lower(probe) NOT LIKE ''%alter %'' AND lower(probe) NOT LIKE ''%create %'' AND lower(probe) NOT LIKE ''%attach %'' AND lower(probe) NOT LIKE ''%pragma%'' AND lower(probe) NOT LIKE ''%replace into%'') AND NOT EXISTS (SELECT 1 FROM bak_20261114_closing_probe_adopt b WHERE b.class = c.class)"},{"type":"sql","db":"AUDIT","sql":"WITH x AS (SELECT c.class, trim(CASE WHEN instr(a.p, char(10)) > 0 THEN substr(a.p, 1, instr(a.p, char(10)) - 1) ELSE a.p END) AS probe FROM remediation_contracts c JOIN (SELECT id, substr(description, instr(description, ''closing probe: '') + 15) AS p FROM agent_issues WHERE status = ''open'' AND instr(description, ''closing probe: SELECT'') > 0) a ON c.class = ''issue-'' || a.id WHERE c.last_verdict LIKE ''monitoring:loop-owned%'') UPDATE remediation_contracts SET verify_probe = (SELECT probe FROM x WHERE x.class = remediation_contracts.class), status = ''active'', attempts = 0, next_due_at = datetime(''now''), last_verdict = ''rearmed: CLOSING-PROBE-ADOPT-1 (the issue''''s own closing probe replaces the loop-owned 48h wait)'' WHERE class IN (SELECT class FROM x WHERE instr(probe, char(59)) = 0 AND length(probe) BETWEEN 30 AND 2000 AND lower(probe) LIKE ''select %'' AND lower(probe) LIKE ''% as expected%'' AND lower(probe) LIKE ''% as observed%'' AND lower(probe) NOT LIKE ''%insert %'' AND lower(probe) NOT LIKE ''%update %'' AND lower(probe) NOT LIKE ''%delete %'' AND lower(probe) NOT LIKE ''%drop %'' AND lower(probe) NOT LIKE ''%alter %'' AND lower(probe) NOT LIKE ''%create %'' AND lower(probe) NOT LIKE ''%attach %'' AND lower(probe) NOT LIKE ''%pragma%'' AND lower(probe) NOT LIKE ''%replace into%'')"}]}', 120000, 1, 1, 1, datetime('now'))
ON CONFLICT(id) DO UPDATE SET name = excluded.name, definition = excluded.definition, version = fleet_tasks.version + 1, enabled = 1, updated_at = excluded.updated_at;

INSERT INTO fleet_crons (name, cron_expr, task_id, enabled, timezone, updated_at)
VALUES ('closing-probe-adopt-hourly', '35 * * * *', 'closing-probe-adopt', 1, 'UTC', datetime('now'))
ON CONFLICT(name) DO UPDATE SET cron_expr = excluded.cron_expr, task_id = excluded.task_id, enabled = excluded.enabled, updated_at = excluded.updated_at;

-- 5. failure mode and its detector
INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius) VALUES
 ('loop-owned-wait-hides-own-probe',
  'an issue a live worker files carries its own machine-checkable closing probe, but its contract is parked as loop-owned monitoring (never probed), so it stays open for 48 h and then goes stale even when the probe passes',
  'contract_probe_templates_loop_merged parks every loop-filed issue as monitoring:loop-owned-48h with next_due_at NULL and trusts the filing loop to close it; most filers (qnfo-cloud-ops resource registry among them) never close their own issues',
  'CLOSING-PROBE-ADOPT-1: the hourly workflow closing-probe-adopt makes the contract adopt the issue''s own read-only closing probe and sets it due, so the remediation consumer closes the issue on a pass and reopens it on relapse',
  'the closing-probe-adopt workflow fired in the last 150 minutes and no open issue older than 3 h has a loop-owned contract next to a closing-probe line', 'fm-loop-owned-wait-hides-own-probe', '2026-11-14', NULL,
  'loop-filed issues with a passing closing probe stay open for days',
  'open issues whose done condition already holds (2026-11-14: 183 open issues behind loop-owned contracts, 53 with their own probe)',
  'open_agent_issues, issue_drain_ratio_24h and the owner reading the open-issue count');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module) VALUES
 ('fm-loop-owned-wait-hides-own-probe', NULL, 'CLOSING-PROBE-ADOPT-1', 'failure-mode detector', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM agent_issues a JOIN remediation_contracts c ON c.class = ''issue-'' || a.id WHERE a.status = ''open'' AND c.last_verdict LIKE ''monitoring:loop-owned%'' AND instr(a.description, ''closing probe: SELECT'') > 0 AND instr(a.description, char(59)) = 0 AND a.created_at < (CAST(strftime(''%s'', ''now'') AS INTEGER) - 10800) * 1000) + (SELECT COUNT(*) FROM fleet_crons WHERE name = ''closing-probe-adopt-hourly'' AND (enabled = 0 OR last_fired IS NULL OR replace(substr(last_fired, 1, 19), ''T'', '' '') < datetime(''now'', ''-150 minutes''))) AS TEXT) AS observed', 'd1-query', 3, 'qnfo-fleet-control', 1, 'active', 'failure-mode');

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'claude-drain-meta-families-1114',
  'an issue that names its own read-only closing probe is closed by that probe, not by waiting for the loop that filed it; a probe that fails keeps it open',
  'CLOSING-PROBE-ADOPT-1: loop-owned monitoring contracts adopt the issue''s own closing probe (one-time and hourly); the 13 dangling-resource probes name their registry row',
  'qnfo-audit 2026-11-14 read-only: 716 open, 200 opened / 78 closed in 24 h; 183 open behind monitoring:loop-owned-48h, 53 with a closing-probe line; 38 CF-RESOURCE-UNUSED-1 filed 00:02Z on a worker-usage timeout, registry ok since 01:01Z',
  'migration merged',
  'remediation_contracts rows of open loop-filed issues that carry a closing-probe line; one fleet task and one cron; no issue is closed directly',
  'the Rollback header of migrations/2026-11-14-closing-probe-adopt.sql',
  'every loop-filed issue with a machine-checkable done condition closes within about an hour of that condition holding, whatever loop filed it',
  'within 3 h at least 38 of the 53 adoptable issues close through auto:verified-remediation-trigger; issue_drain_ratio_24h rises',
  'none',
  'd1:qnfo-audit read-only, node:sqlite replay in migrations/closing-probe-adopt.test.mjs'
WHERE NOT EXISTS (SELECT 1 FROM decision_log WHERE instr(action, 'CLOSING-PROBE-ADOPT-1:') = 1);
